const fmt = (n) => n ? n.toLocaleString("vi-VN") + " đ" : "Liên hệ";
let activeCat = null, cart = [], modalProduct = null;
const sidebar = document.getElementById("sidebar");
const catalog = document.getElementById("catalog");
const searchInput = document.getElementById("searchInput");
const priceFilter = document.getElementById("priceFilter");
const resultCount = document.getElementById("resultCount");
const emptyMsg = document.getElementById("emptyMsg");

function escHtml(s){ return s.replace(/&/g,"&amp;").replace(/</g,"&lt;").replace(/"/g,"&quot;"); }
function filtered(){
  const q = (searchInput.value || "").toLowerCase().trim();
  const pf = priceFilter.value;
  return PRODUCTS.filter(p => {
    const okCat = !activeCat || p.cat === activeCat;
    const okQ = !q || (p.name + " " + p.cat).toLowerCase().includes(q);
    const okP = pf === "all" || (pf === "priced" ? p.price : !p.price);
    return okCat && okQ && okP;
  });
}
function cardHtml(p, i){
  return `<article class="card">
    <button class="card-img" type="button" data-open="${i}" aria-label="Xem chi tiết ${escHtml(p.name)}"><img src="${p.img}" alt="${escHtml(p.name)}" loading="lazy" onerror="this.style.display='none';this.parentElement.classList.add('img-missing');this.parentElement.setAttribute('data-missing','Ảnh chưa tải được')"></button>
    <div class="card-body">
      <p class="card-cat">${p.cat}</p>
      <h3><button type="button" data-open="${i}">${escHtml(p.name)}</button></h3>
      <p class="card-price ${p.price ? "" : "contact"}">${fmt(p.price)}</p>
      <div class="card-actions">
        <button class="btn btn-ghost" type="button" data-add="${i}">+ Quan tâm</button>
        <a class="btn btn-primary" href="tel:0932077059">Gọi báo giá</a>
      </div>
    </div>
  </article>`;
}
function renderSidebar(){
  if (activeCat) { for (const g of GROUPS) { if (g.cats.includes(activeCat)) expandedGroups.add(g.name); } }
  const allBtn = `<button class="side-btn${!activeCat ? " active" : ""}" type="button" data-cat="">Tất cả danh mục <span>${PRODUCTS.length}</span></button>`;
  const groupsHtml = GROUPS.map(g => {
    const open = expandedGroups.has(g.name);
    const total = PRODUCTS.filter(p => g.cats.includes(p.cat)).length;
    const subs = g.cats.map(c => {
      const n = PRODUCTS.filter(p => p.cat === c).length;
      return `<button class="side-btn side-sub-btn${activeCat === c ? " active" : ""}" type="button" data-cat="${escHtml(c)}">${c} <span>${n}</span></button>`;
    }).join("");
    return `<div class="side-group"><button class="side-group-btn${open ? " open" : ""}" type="button" data-group="${escHtml(g.name)}"><span>${g.name}</span><span class="side-group-meta"><span>${total}</span><span class="side-arrow">${open ? "▾" : "▸"}</span></span></button><div class="side-sub" ${open ? "" : "hidden"}>${subs}</div></div>`;
  }).join("");
  sidebar.innerHTML = allBtn + groupsHtml;
  sidebar.querySelectorAll(".side-group-btn").forEach(b => b.addEventListener("click", () => {
    const name = b.dataset.group;
    if (expandedGroups.has(name)) expandedGroups.delete(name); else expandedGroups.add(name);
    renderSidebar();
  }));
  sidebar.querySelectorAll(".side-sub-btn").forEach(b => b.addEventListener("click", () => {
    activeCat = b.dataset.cat; renderSidebar(); renderCatalog();
    const el = document.getElementById("floor-" + CATEGORIES.indexOf(activeCat)); if (el) el.scrollIntoView({behavior:"smooth"});
  }));
  sidebar.querySelectorAll(".side-btn[data-cat='']").forEach(b => b.addEventListener("click", () => { activeCat = null; renderSidebar(); renderCatalog(); }));
}
let expandedGroups = new Set([GROUPS[0].name]);
function renderCatalog(){
  const list = filtered();
  const isAllView = !activeCat && !(searchInput.value || "").trim() && priceFilter.value === "all";
  resultCount.textContent = (activeCat ? `Danh mục: ${activeCat} · ` : "") + `${list.length} / ${PRODUCTS.length} sản phẩm.` + (isAllView ? " Ở chế độ Tất cả, mỗi danh mục chỉ hiện 4 sản phẩm đầu." : "");
  emptyMsg.hidden = list.length > 0;
  const catsToShow = activeCat ? [activeCat] : CATEGORIES;
  catalog.innerHTML = catsToShow.map(c => {
    const items = list.filter(p => p.cat === c);
    const idx = CATEGORIES.indexOf(c);
    const shown = (isAllView && items.length > 4) ? items.slice(0, 4) : items;
    const body = items.length ? `<div class="floor-grid">${shown.map(p => cardHtml(p, PRODUCTS.indexOf(p))).join("")}</div>` + ((isAllView && items.length > 4) ? `<button class="floor-more" type="button" data-showcat="${escHtml(c)}">Xem thêm ${items.length - 4} sản phẩm trong danh mục này →</button>` : "")
      : `<p class="floor-empty">Không có sản phẩm khớp trong danh mục này. Gọi 0932.077.059 để hỏi hàng tương đương.</p>`;
    const countText = (isAllView && items.length > 4) ? `Hiện 4 / ${items.length} sản phẩm` : `${items.length} sản phẩm`;
    return `<section class="floor" id="floor-${idx}"><div class="floor-head"><h2><span class="floor-no">${idx + 1}</span>${c}</h2><span class="floor-count">${countText}</span></div>${body}</section>`;
  }).join("");
  catalog.querySelectorAll("[data-open]").forEach(b => b.addEventListener("click", () => openModal(PRODUCTS[+b.dataset.open])));
  catalog.querySelectorAll("[data-add]").forEach(b => b.addEventListener("click", () => addToCart(PRODUCTS[+b.dataset.add])));
  catalog.querySelectorAll("[data-showcat]").forEach(b => b.addEventListener("click", () => {
    activeCat = b.dataset.showcat; renderSidebar(); renderCatalog();
    const el = document.getElementById("floor-" + CATEGORIES.indexOf(activeCat)); if (el) el.scrollIntoView({behavior:"smooth"});
  }));
}
function updateCart(){
  document.getElementById("cartCount").textContent = cart.length;
  document.getElementById("stickyCartCount").textContent = cart.length;
  const listEl = document.getElementById("drawerList");
  listEl.innerHTML = cart.length ? cart.map((p, i) => `<li><span><strong>${escHtml(p.name)}</strong><br><small>${p.cat} · ${fmt(p.price)}</small></span><button type="button" data-remove="${i}">Xóa</button></li>`).join("")
    : `<li>Chưa có sản phẩm nào. Bấm “+ Quan tâm” ở một sản phẩm để gom tên cần hỏi giá.</li>`;
  listEl.querySelectorAll("[data-remove]").forEach(b => b.addEventListener("click", () => { cart.splice(+b.dataset.remove, 1); updateCart(); }));
}
function addToCart(p){ if (!cart.some(x => x.url === p.url)) cart.push(p); updateCart(); openDrawer(); }
function openDrawer(){ document.getElementById("cartDrawer").hidden = false; document.getElementById("drawerBackdrop").hidden = false; }
function closeDrawer(){ document.getElementById("cartDrawer").hidden = true; document.getElementById("drawerBackdrop").hidden = true; }
function openModal(p){
  modalProduct = p;
  document.getElementById("modalCat").textContent = p.cat;
  document.getElementById("modalCat2").textContent = p.cat;
  document.getElementById("modalName").textContent = p.name;
  const priceEl = document.getElementById("modalPrice"); priceEl.textContent = fmt(p.price); priceEl.className = "modal-price" + (p.price ? "" : " contact");
  document.getElementById("modalDesc").textContent = p.desc;
  document.getElementById("modalImg").src = p.img; document.getElementById("modalImg").alt = p.name;
  document.getElementById("productModal").showModal();
}
document.getElementById("cartBtn").addEventListener("click", openDrawer);
document.getElementById("stickyCartBtn").addEventListener("click", openDrawer);
document.getElementById("closeDrawer").addEventListener("click", closeDrawer);
document.getElementById("drawerBackdrop").addEventListener("click", closeDrawer);
document.getElementById("clearFilter").addEventListener("click", () => { activeCat = null; searchInput.value = ""; priceFilter.value = "all"; renderSidebar(); renderCatalog(); });
document.getElementById("modalAdd").addEventListener("click", () => { if (modalProduct) { addToCart(modalProduct); document.getElementById("productModal").close(); } });
searchInput.addEventListener("input", renderCatalog);
priceFilter.addEventListener("change", renderCatalog);
document.addEventListener("keydown", (e) => { if (e.key === "Escape") closeDrawer(); });
renderSidebar(); renderCatalog(); updateCart();
